import os
import boto3


def _build_s3_client():
    client_kwargs = {}
    akid = os.getenv("AWS_ACCESS_KEY_ID")
    secret = os.getenv("AWS_SECRET_ACCESS_KEY")
    token = os.getenv("AWS_SESSION_TOKEN")
    region = os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION")
    endpoint = os.getenv("AWS_S3_ENDPOINT_URL")

    if akid and secret:
        client_kwargs["aws_access_key_id"] = akid
        client_kwargs["aws_secret_access_key"] = secret
    if token:
        client_kwargs["aws_session_token"] = token
    if region:
        client_kwargs["region_name"] = region
    if endpoint:
        client_kwargs["endpoint_url"] = endpoint

    return boto3.client("s3", **client_kwargs)


def upload_file(file_path, bucket_name, object_name=None):
    s3 = _build_s3_client()

    if object_name is None:
        object_name = os.path.basename(file_path)

    extra_args = {}
    sse = os.getenv("S3_SSE") or os.getenv("AWS_S3_SSE")
    kms_key = os.getenv("S3_SSE_KMS_KEY_ID") or os.getenv("AWS_S3_SSE_KMS_KEY_ID")
    if sse:
        extra_args["ServerSideEncryption"] = sse
    if kms_key:
        extra_args["SSEKMSKeyId"] = kms_key

    if extra_args:
        s3.upload_file(file_path, bucket_name, object_name, ExtraArgs=extra_args)
    else:
        s3.upload_file(file_path, bucket_name, object_name)

    print("Upload complete.")


if __name__ == "__main__":
    import sys
    if len(sys.argv) < 3:
        print("Usage: python uploader.py <file_path> <bucket_name> [object_name]")
        sys.exit(1)
    path, bucket = sys.argv[1], sys.argv[2]
    key = sys.argv[3] if len(sys.argv) > 3 else None
    upload_file(path, bucket, key)

